-- DESIGN REFERENCE ONLY. Not a release migration and not Cequre-generated DDL.
-- Translate to canonical .cequre schemas plus reviewed supplemental migrations
-- after verifying installed runtime names/types/locking in milestone 1.
-- PostgreSQL; UUIDs are generated by trusted service code.
BEGIN;

CREATE TABLE tenants (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (length(name) BETWEEN 1 AND 160),
    active boolean NOT NULL DEFAULT true,
    max_active_intelligence integer NOT NULL DEFAULT 2 CHECK (max_active_intelligence > 0),
    max_active_browser integer NOT NULL DEFAULT 1 CHECK (max_active_browser > 0),
    created_at timestamptz NOT NULL DEFAULT now()
);

-- auth_subject refers to this service's Cequre auth identity, not platform tables.
CREATE TABLE tenant_memberships (
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    auth_subject text NOT NULL,
    role text NOT NULL CHECK (role IN ('operator', 'candidate')),
    candidate_subject_ref text,
    active boolean NOT NULL DEFAULT true,
    PRIMARY KEY (tenant_id, auth_subject),
    CHECK (role <> 'candidate' OR candidate_subject_ref IS NOT NULL)
);

CREATE TABLE api_clients (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    name text NOT NULL,
    category text NOT NULL CHECK (category IN ('first_party', 'external')),
    active boolean NOT NULL DEFAULT true,
    -- An empty grant list gives no candidate access. Validated by auth domain.
    candidate_grants jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    CHECK (jsonb_typeof(candidate_grants) = 'array')
);

CREATE TABLE api_keys (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    secret_digest bytea NOT NULL CHECK (octet_length(secret_digest) = 32),
    pepper_version integer NOT NULL CHECK (pepper_version > 0),
    scopes text[] NOT NULL,
    expires_at timestamptz,
    revoked_at timestamptz,
    last_used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, client_id) REFERENCES api_clients(tenant_id, id),
    UNIQUE (tenant_id, id),
    CHECK (expires_at IS NULL OR expires_at > created_at)
);
CREATE INDEX api_keys_client_idx ON api_keys(tenant_id, client_id);

CREATE TABLE candidate_snapshots (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    subject_ref text NOT NULL CHECK (length(subject_ref) BETWEEN 1 AND 128),
    snapshot jsonb NOT NULL CHECK (jsonb_typeof(snapshot) = 'object'),
    input_hash bytea NOT NULL CHECK (octet_length(input_hash) = 32),
    consent_purpose text NOT NULL,
    consent_granted_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, id, subject_ref),
    CHECK (expires_at > created_at)
);
CREATE INDEX candidate_subject_idx ON candidate_snapshots(tenant_id, subject_ref);
CREATE INDEX candidate_expiry_idx ON candidate_snapshots(expires_at);

CREATE TABLE job_snapshots (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    input jsonb NOT NULL CHECK (jsonb_typeof(input) = 'object'),
    normalized_job jsonb,
    content_hash bytea NOT NULL CHECK (octet_length(content_hash) = 32),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    UNIQUE (tenant_id, id),
    CHECK (expires_at > created_at)
);

CREATE INDEX job_expiry_idx ON job_snapshots(expires_at);

CREATE TABLE runs (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    client_id uuid NOT NULL,
    candidate_snapshot_id uuid,
    candidate_subject_ref text,
    -- Nullable only once terminal input has been purged; metadata may outlive PII.
    job_snapshot_id uuid,
    operation text NOT NULL CHECK (operation IN ('job_analysis', 'match', 'cv_tailoring', 'application_prepare')),
    status text NOT NULL DEFAULT 'queued' CHECK (status IN (
        'queued', 'validating', 'running', 'awaiting_user_action', 'awaiting_approval',
        'completed', 'partially_completed', 'failed', 'cancelled', 'expired'
    )),
    phase text NOT NULL DEFAULT 'prepare' CHECK (phase IN ('prepare', 'submit', 'reconcile')),
    options jsonb NOT NULL DEFAULT '{}'::jsonb,
    version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
    fencing_token bigint NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
    event_sequence bigint NOT NULL DEFAULT 0 CHECK (event_sequence >= 0),
    progress integer NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 100),
    attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    max_attempts integer NOT NULL DEFAULT 3 CHECK (max_attempts BETWEEN 1 AND 3),
    correlation_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    started_at timestamptz,
    completed_at timestamptz,
    deadline_at timestamptz NOT NULL,
    cancel_requested_at timestamptz,
    result jsonb,
    error jsonb,
    usage jsonb NOT NULL DEFAULT '{}'::jsonb,
    submission_status text NOT NULL DEFAULT 'not_attempted'
        CHECK (submission_status IN ('not_attempted', 'submitted', 'unknown', 'not_submitted')),
    FOREIGN KEY (tenant_id, client_id) REFERENCES api_clients(tenant_id, id),
    FOREIGN KEY (tenant_id, candidate_snapshot_id, candidate_subject_ref)
        REFERENCES candidate_snapshots(tenant_id, id, subject_ref),
    FOREIGN KEY (tenant_id, job_snapshot_id) REFERENCES job_snapshots(tenant_id, id),
    UNIQUE (tenant_id, id),
    CHECK (status IN ('completed', 'partially_completed', 'failed', 'cancelled', 'expired')
        OR job_snapshot_id IS NOT NULL),
    CHECK (operation = 'job_analysis'
        OR status IN ('completed', 'partially_completed', 'failed', 'cancelled', 'expired')
        OR candidate_snapshot_id IS NOT NULL),
    CHECK ((candidate_snapshot_id IS NULL) = (candidate_subject_ref IS NULL)),
    CHECK (deadline_at > created_at),
    CHECK (status NOT IN ('completed', 'partially_completed', 'failed', 'cancelled', 'expired')
        OR completed_at IS NOT NULL),
    CHECK (submission_status <> 'submitted' OR operation = 'application_prepare')
);
CREATE INDEX runs_owner_idx ON runs(tenant_id, client_id, created_at DESC);
CREATE INDEX runs_subject_idx ON runs(tenant_id, candidate_subject_ref);
CREATE INDEX runs_recovery_idx ON runs(status, deadline_at)
    WHERE status IN ('queued', 'validating', 'running', 'awaiting_user_action', 'awaiting_approval');

CREATE TABLE idempotency_records (
    tenant_id uuid NOT NULL,
    client_id uuid NOT NULL,
    key text NOT NULL CHECK (length(key) BETWEEN 8 AND 128),
    request_hash bytea NOT NULL CHECK (octet_length(request_hash) = 32),
    -- Public aliases canonicalize to the same operation before hashing.
    run_id uuid NOT NULL,
    accepted_response jsonb NOT NULL,
    accepted_status integer NOT NULL DEFAULT 202 CHECK (accepted_status = 202),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    PRIMARY KEY (tenant_id, client_id, key),
    FOREIGN KEY (tenant_id, client_id) REFERENCES api_clients(tenant_id, id),
    FOREIGN KEY (tenant_id, run_id) REFERENCES runs(tenant_id, id),
    CHECK (expires_at > created_at)
);
CREATE INDEX idempotency_expiry_idx ON idempotency_records(expires_at);

CREATE TABLE run_events (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    sequence bigint NOT NULL CHECK (sequence > 0),
    type text NOT NULL,
    status text NOT NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, run_id) REFERENCES runs(tenant_id, id),
    UNIQUE (tenant_id, run_id, sequence),
    CHECK (octet_length(metadata::text) <= 2048)
);

CREATE TABLE run_attempts (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    attempt_number integer NOT NULL CHECK (attempt_number > 0),
    phase text NOT NULL CHECK (phase IN ('prepare', 'submit', 'reconcile')),
    fencing_token bigint NOT NULL CHECK (fencing_token > 0),
    worker_id text NOT NULL,
    lease_expires_at timestamptz NOT NULL,
    heartbeat_at timestamptz NOT NULL,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    submission_intent_at timestamptz,
    -- Non-PII receipt metadata; sensitive payloads are private artifacts.
    observed_receipt jsonb,
    error_code text,
    FOREIGN KEY (tenant_id, run_id) REFERENCES runs(tenant_id, id),
    UNIQUE (tenant_id, run_id, attempt_number),
    CHECK (submission_intent_at IS NULL OR phase = 'submit')
);
CREATE INDEX attempts_lease_idx ON run_attempts(lease_expires_at) WHERE finished_at IS NULL;
-- Even a worker crash does not permit another submit intent for this run.
CREATE UNIQUE INDEX one_submission_intent_per_run ON run_attempts(tenant_id, run_id)
    WHERE submission_intent_at IS NOT NULL;

CREATE TABLE artifacts (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('tailored_cv', 'application_draft', 'application_answers', 'diagnostic')),
    version integer NOT NULL CHECK (version > 0),
    content jsonb,
    private_object_key text,
    content_hash bytea NOT NULL CHECK (octet_length(content_hash) = 32),
    media_type text NOT NULL DEFAULT 'application/json',
    byte_size bigint NOT NULL CHECK (byte_size >= 0),
    purged_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    FOREIGN KEY (tenant_id, run_id) REFERENCES runs(tenant_id, id),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, run_id, id, version),
    UNIQUE (tenant_id, run_id, kind, version),
    CHECK (content IS NOT NULL OR private_object_key IS NOT NULL OR purged_at IS NOT NULL),
    CHECK (purged_at IS NULL OR (content IS NULL AND private_object_key IS NULL)),
    CHECK (expires_at > created_at)
);
CREATE INDEX artifacts_expiry_idx ON artifacts(expires_at);

CREATE TABLE approvals (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    draft_artifact_id uuid NOT NULL,
    draft_version integer NOT NULL,
    draft_hash bytea NOT NULL CHECK (octet_length(draft_hash) = 32),
    approved_payload_digest bytea NOT NULL CHECK (octet_length(approved_payload_digest) = 32),
    actor_subject text NOT NULL,
    authority_issuer text NOT NULL,
    proof_jti text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    consumed_at timestamptz,
    invalidated_at timestamptz,
    FOREIGN KEY (tenant_id, run_id, draft_artifact_id, draft_version)
        REFERENCES artifacts(tenant_id, run_id, id, version),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, authority_issuer, proof_jti),
    CHECK (expires_at > created_at),
    CHECK (consumed_at IS NULL OR consumed_at >= created_at)
);
CREATE UNIQUE INDEX one_active_approval_per_run ON approvals(tenant_id, run_id)
    WHERE consumed_at IS NULL AND invalidated_at IS NULL;

CREATE TABLE dispatch_outbox (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    phase text NOT NULL CHECK (phase IN ('prepare', 'submit', 'reconcile')),
    dispatch_number integer NOT NULL CHECK (dispatch_number > 0),
    available_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    locked_until timestamptz,
    last_error_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, run_id) REFERENCES runs(tenant_id, id),
    UNIQUE (tenant_id, run_id, dispatch_number)
);
CREATE INDEX pending_dispatch_idx ON dispatch_outbox(available_at) WHERE published_at IS NULL;

-- Added with deletion implementation; not a client-controlled platform user table.
CREATE TABLE data_deletions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id),
    subject_ref text NOT NULL,
    requested_by text NOT NULL,
    status text NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    error_code text,
    UNIQUE (tenant_id, id),
    CHECK (status <> 'completed' OR completed_at IS NOT NULL)
);
CREATE UNIQUE INDEX one_active_deletion_per_subject ON data_deletions(tenant_id, subject_ref)
    WHERE status IN ('queued', 'running');
CREATE INDEX deletion_subject_idx ON data_deletions(tenant_id, subject_ref, created_at DESC);

-- Run state transition graph, candidate grants, source-fact validation, digest
-- binding, revocation, immutable artifacts, and one-use approval are enforced
-- in trusted domain/repository code and tested through HTTP. CHECKs alone are
-- not a complete authorization or lifecycle mechanism. Restrict DB roles.
-- Purge child rows in reviewed order; no broad CASCADE that destroys audit
-- or idempotency unexpectedly. Active executions must be fenced first.
-- After terminal state, redact result/error/subject metadata and detach snapshot
-- FKs transactionally before purging snapshots. Redact approval/artifact PII or
-- retain only digest-only audit records. Delete idempotency/outbox before runs.
-- Deletion ledger subject_ref is later replaced with an expiring keyed digest
-- for backup replay, not retained indefinitely as a personal identifier.
COMMIT;
